                <td data-testid="person-aged-61">{{ money(agedOf(p.id).over60) }}</td>
                <td data-testid="person-active">{{ activeIds().has(p.id) ? 'yes' : 'no' }}</td>
                <td>
                  <span data-testid="person-retired">{{ p.retired ? 'yes' : 'no' }}</span>
